def newton(f, f_derivert, x0, toleranse=1e-10, maks_iter=100):
    x = x0
    for i in range(maks_iter):
        fx = f(x)
        if abs(fx) < toleranse:
            return x
        fpx = f_derivert(x)
        if fpx == 0:
            raise ValueError("Derivert lik null")
        x = x - fx / fpx
    return x
